package org.apache.commons.lang;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.StringWriter;
import java.io.IOException;

public class AgentBRT_Lang_52_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        StringWriter writer = new StringWriter();
        String input = "This is a test / string";
        try {
            StringEscapeUtils.escapeJavaStyleString(writer, input, false);
            String result = writer.toString();
            // Assuming the expected behavior is to escape '/' as '\/'
            assertEquals("This is a test \/ string", result);
        } catch (IOException e) {
            fail("IOException should not occur");
        }
    }
}

